INSERT INTO cards (id, sender_id, sender_name, recognition_reason, created_at, updated_at) VALUES ('d9a3689e-2ef2-4a2a-8d25-acda85f923e9', 'f1f7264d-5a6c-4fef-82e9-a122f9a332d0', 'Alex Zu (SZX)', '向Bingye Li表达诚挚的感谢！你对细节的关注让我们的产品质量得到了显著提升。你在系统重构中展现出的专业能力令人印象深刻。你是我们团队的骄傲！ 你是我们团队的骄傲！ 感谢你一直以来的支持和帮助！ 希望我们能继续保持这样的合作默契！', '2025-01-30 16:40:57', '2025-01-30 16:40:57');
INSERT INTO cards (id, sender_id, sender_name, recognition_reason, created_at, updated_at) VALUES ('67df9db8-7294-49d7-b6f7-00822939f170', 'cd7e9fb0-d844-441e-aac4-b8c21d36ef7c', 'Christopher Li (SZX)', 'Bingye Li，非常感谢你在Q1产品迭代中的贡献！你的团队协作精神让整个项目进展得更加顺利。你的努力和专注让整个项目得以顺利完成。期待未来能有更多合作的机会！ 期待你在未来取得更大的成就！ 期待你在未来取得更大的成就！', '2025-01-30 17:30:30', '2025-01-30 17:30:30');
INSERT INTO cards (id, sender_id, sender_name, recognition_reason, created_at, updated_at) VALUES ('bcc2c0ad-44fe-4e1f-9781-58f7367c769b', 'cd7e9fb0-d844-441e-aac4-b8c21d36ef7c', 'Christopher Li (SZX)', '感谢Bingye Li在过去一段时间里的辛勤付出！你的沟通能力很强，能够清晰地表达技术方案和想法。你的工作态度和专业素养值得我们每个人学习。你的努力不会被忽视，继续加油！ 你的努力不会被忽视，继续加油！', '2025-01-30 19:35:36', '2025-01-30 19:35:36');
INSERT INTO cards (id, sender_id, sender_name, recognition_reason, created_at, updated_at) VALUES ('2c465a77-01ad-4e22-93e1-7d0e8a244985', 'd3dc438c-1de2-49dc-ae8b-8dffb7fcb2cc', 'Youshan Li (SZX)', '感谢Zehui Lin一直以来的支持！你总是愿意分享知识，帮助团队成员共同成长。在技术架构升级项目中，你的付出让我们看到了团队协作的力量。你的贡献对团队意义重大！ 很高兴能和你一起工作！ 期待你在未来取得更大的成就！', '2025-01-30 20:06:06', '2025-01-30 20:06:06');
INSERT INTO cards (id, sender_id, sender_name, recognition_reason, created_at, updated_at) VALUES ('61183cee-6b12-47ec-b5e6-8999c12b5961', 'f1f7264d-5a6c-4fef-82e9-a122f9a332d0', 'Alex Zu (SZX)', '感谢Shawine Wu一直以来的支持！你主动承担了很多额外的工作，确保项目按时交付。在Q1产品迭代项目中，你的付出让我们看到了团队协作的力量。你的贡献对团队意义重大！ 很高兴能和你一起工作！ 希望我们能继续保持这样的合作默契！', '2025-01-30 20:07:26', '2025-01-30 20:07:26');
INSERT INTO cards (id, sender_id, sender_name, recognition_reason, created_at, updated_at) VALUES ('a77d9a53-41c8-4120-94ce-f04094e60fc9', 'f1f7264d-5a6c-4fef-82e9-a122f9a332d0', 'Alex Zu (SZX)', '感谢Bingye Li一直以来的支持！你总是愿意分享知识，帮助团队成员共同成长。在文档完善项目中，你的付出让我们看到了团队协作的力量。感谢你为团队带来的正能量！ 期待未来能有更多合作的机会！ 你的专业精神值得我们每个人学习！', '2025-01-30 20:54:08', '2025-01-30 20:54:08');
